75	namespace ex = ::comdare::cache_engine::builder::experiment;
76	namespace cx = ::comdare::builder::xml;
77	namespace ms = ::comdare::cache_engine::measurement; // INC-3: kMeasurementAxisRegistry (Kategorie-Namen)
