441	/// validate_experiment_profile — DIE reine Pruef-Logik (read-only). `registry_dir` = Verzeichnis, gegen das
442	/// die je-engine `registry`-Dateinamen aufgeloest werden (leer = (4)+(5) uebersprungen). Schreibt KEINE Datei,
443	/// baut KEINE DLL, misst NICHTS. Gibt das Ergebnis-POD zurueck.
444	[[nodiscard]] inline ExperimentValidationResult
445	validate_experiment_profile(cx::ExperimentProfile const& ep, std::filesystem::path const& registry_dir = {}) {
446	    ExperimentValidationResult r;
447	
448	    // ── (1) GENAU 2 engines. ──
449	    r.engines_checked = ep.engines.size();
450	    if (ep.engines.size() != 2) {
451	        r.ok = false;
452	        r.errors.push_back("EXPERIMENT braucht GENAU 2 <execution_engines><engine> (ee_ce + ee_prt), gefunden: " +
453	                           std::to_string(ep.engines.size()) + ".");
454	    }
455	
456	    // ── (2) mindestens 1 phase. ──
457	    if (ep.phases.empty()) {
458	        r.ok = false;
459	        r.errors.push_back("EXPERIMENT braucht mindestens 1 <phases><phase> (die Kompositionalen Joins).");
460	    }
461	
462	    // ── (3) jede phase.merge ∈ MergeStrategy-Enum. ──
463	    std::set<std::string> valid_merges;
464	    for (auto const s : kExperimentMergeStrategies) valid_merges.insert(std::string{merge_strategy_name(s)});
465	    for (auto const& ph : ep.phases) {
466	        ++r.phases_checked;
467	        if (valid_merges.find(ph.merge) == valid_merges.end()) {
468	            r.ok = false;
469	            std::vector<std::string> const vm(valid_merges.begin(), valid_merges.end());
470	            r.errors.push_back(
471	                "UNGUELTIGE Merge-Strategie <phase name=\"" + ph.name + "\" merge=\"" + ph.merge +
472	                "\">: kein MergeStrategy-Enum-Wert (pruefling_merge.hpp). Gueltig = " + preview_values(vm));
473	        }
474	    }
475	
476	    // ── (4)+(5): Registry-Dateien existieren + allowed_variants ⊆ ce-Registry-baustein-names. ──
477	    if (registry_dir.empty()) {
478	        r.warnings.push_back("registry_dir nicht gesetzt: Registry-Existenz (4) + allowed_variants (5) "
479	                             "uebersprungen — rein strukturelle Validierung.");
480	    } else {
481	        std::optional<RegistryContents> ce_registry; // die Registry mit engine="cache_engine"
482	        for (auto const& e : ep.engines) {
483	            std::filesystem::path const rf = registry_dir / e.registry;
484	            if (!std::filesystem::exists(rf)) {
485	                r.ok = false;
486	                r.errors.push_back("REGISTRY-Datei fehlt <engine id=\"" + e.id + "\" registry=\"" + e.registry +
487	                                   "\">: nicht gefunden unter " + rf.string() + ".");
488	                continue;
489	            }
490	            auto parsed = read_axis_registry(rf);
491	            if (!parsed) {
492	                r.warnings.push_back(
493	                    "Registry <engine id=\"" + e.id + "\" registry=\"" + e.registry +
494	                    "\"> nicht als comdare_axis_registry lesbar — allowed_variants-Pruefung entfaellt.");
495	                continue;
496	            }
497	            if (parsed->engine == "cache_engine") ce_registry = std::move(parsed);
498	        }
499	        // (5) allowed_variants gegen die ce-Registry (Golden-Doku: Teilmenge der ce-`baustein name`-Werte).
500	        if (!ep.axes_default_lookup.empty()) {
501	            if (!ce_registry) {
502	                r.warnings.push_back("keine ce-Registry (engine=\"cache_engine\") aufloesbar — "
503	                                     "allowed_variants (5) nicht gegen die Registry geprueft.");
504	            } else {
505	                for (auto const& ax : ep.axes_default_lookup) {
506	                    auto it = ce_registry->axis_names.find(ax.ref);
507	                    if (it == ce_registry->axis_names.end()) {
508	                        r.ok = false;
509	                        r.errors.push_back("UNBEKANNTE Achse <axes_default_lookup><axis ref=\"" + ax.ref +
510	                                           "\">: kein axis-id der ce-Registry (cache_engine_axis_registry.xml).");
511	                        continue;
512	                    }
513	                    std::set<std::string> const& valid = it->second;
514	                    for (auto const& v : ax.allowed_variants) {
515	                        ++r.variants_checked;
516	                        if (valid.find(v) == valid.end()) {
517	                            r.ok = false;
518	                            std::vector<std::string> const vv(valid.begin(), valid.end());
519	                            r.errors.push_back("UNGUELTIGE allowed_variant <axis ref=\"" + ax.ref + "\">: \"" + v +
520	                                               "\" ist kein `baustein name` dieser ce-Registry-Achse. Gueltig = " +
521	                                               preview_values(vv));
522	                        }
523	                    }
524	                }
525	            }
526	        }
527	    }
528	
529	    // ── (6) jede category ∈ kAllMeasurementCategories (16). Single-Source = das Enum + der Registry-Name. ──
530	    if (!ep.measurement_categories.empty()) {
531	        std::set<std::string> valid_categories;
532	        for (auto const cat : ms::kAllMeasurementCategories)
533	            valid_categories.insert(std::string{ms::axis_info(cat).name});
534	        std::set<std::string> seen_categories;
535	        for (auto const& cat : ep.measurement_categories) {
536	            ++r.categories_checked;
537	            if (valid_categories.find(cat) == valid_categories.end()) {
538	                r.ok = false;
539	                std::vector<std::string> const valid(valid_categories.begin(), valid_categories.end());
540	                r.errors.push_back("UNGUELTIGE Mess-Kategorie <measurement_categories><category name=\"" + cat +
541	                                   "\">: kein MeasurementCategory-Name (kAllMeasurementCategories, 16). Gueltig = " +
542	                                   preview_values(valid));
543	            } else if (!seen_categories.insert(cat).second) {
544	                r.warnings.push_back("category name=\"" + cat +
545	                                     "\": mehrfach deklariert — redundante Spalten-Projektion (nicht fatal).");
546	            }
547	        }
548	    }
549	
550	    return r;
551	}
