152	/// sota_module_for — das reale Lebewesen-Modul für ein (Stufe, Lebewesen)-Paar des Profils. nullopt, wenn das
153	/// Paar (in diesem Pilot) NICHT real baubar ist (ehrlich → leere Quelle beim Caller). #178: dispatcht auf die
154	/// STUFE (merge) — die mechanische Wahrheit — NICHT auf den Reihen-id; der Reihen-Tag wird via stufe_to_reihe(merge)
155	/// abgeleitet (binary_id-Namensraum). Mechanik:
156	///   Stufe1_CeOnly           → das isolierte Lebewesen (build_sota_series_a_modules) → Reihe A.
157	///   Stufe2_PrueflingReplace → <Host>PrtStufe2ReplaceComposition je SOTA-Host (PRT-ART ersetzt den path_compression-
158	///                             Slot) → Reihe A; prt_art-Host → nullopt (M-CE-10 per-Host, 2026-07-14).
159	///   Stufe3_FullJoin         → <Host>PrtStufe3FullJoinComposition je SOTA-Host → Reihe B; prt_art-Host → nullopt.
160	/// M-CE-10 (2026-07-14): Stufe2 ist per-Host aufgefächert (der frühere HOT-Pilot war die EINE St2-Binary) — jetzt
161	/// symmetrisch zu Stufe3 (je SOTA-Host eine distinkte reale Komposition, host_lebewesen == lebewesen).
162	[[nodiscard]] inline std::optional<SotaModule> sota_module_for(std::string const& merge, std::string const& lebewesen) {
163	    if (merge == "Stufe1_CeOnly") {
164	        for (auto const& m : build_sota_series_a_modules())
165	            if (m.lebewesen == lebewesen) return m;
166	        return std::nullopt;
167	    }
168	    std::string const reihe = stufe_to_reihe(merge); // #178: Reihe mechanisch aus der Stufe (A für St2, B für St3)
169	    if (merge == "Stufe2_PrueflingReplace") {
170	        // M-CE-10 (per-Host-Stufe2, 2026-07-14, Ledger :1134 — bau-relevant mit F/G): ANALOG zu Stufe3 (unten)
171	        // fächert Stufe2 jetzt je SOTA-Host eine distinkte <Host>PrtStufe2ReplaceComposition (Host stellt 18 Achsen,
172	        // PRT-ART ersetzt den path_compression-Slot). Die binary_id ist damit GENUINE per-Host distinkt (verschiedene
173	        // Hosts = verschiedene Kompositionen — KEIN Fake-id für byte-identischen HOT-Code, der alte Anti-Phantom-
174	        // Fall entfällt). host_lebewesen == lebewesen (der reale Host trägt den H2-Score). prt_art-als-Host ist
175	        // degeneriert (in Reihe A/Stufe1 bereits isoliert) → nullopt (ehrlich, keine Stufe1-Duplikation unter St2).
176	        struct B {
177	            std::string_view type;
178	            std::string_view name;
179	        };
180	        auto pick = [&](std::string const& l) -> std::optional<B> {
181	            if (l == "art")
182	                return B{"::comdare::cache_engine::compositions::ArtPrtStufe2ReplaceComposition",
183	                         cmp::ArtPrtStufe2ReplaceComposition::name};
184	            if (l == "hot")
185	                return B{"::comdare::cache_engine::compositions::HotPrtStufe2ReplaceComposition",
186	                         cmp::HotPrtStufe2ReplaceComposition::name};
187	            if (l == "masstree")
188	                return B{"::comdare::cache_engine::compositions::MasstreePrtStufe2ReplaceComposition",
189	                         cmp::MasstreePrtStufe2ReplaceComposition::name};
190	            if (l == "surf")
191	                return B{"::comdare::cache_engine::compositions::SurfPrtStufe2ReplaceComposition",
192	                         cmp::SurfPrtStufe2ReplaceComposition::name};
193	            if (l == "start")
194	                return B{"::comdare::cache_engine::compositions::StartPrtStufe2ReplaceComposition",
195	                         cmp::StartPrtStufe2ReplaceComposition::name};
196	            if (l == "wormhole")
197	                return B{"::comdare::cache_engine::compositions::WormholePrtStufe2ReplaceComposition",
198	                         cmp::WormholePrtStufe2ReplaceComposition::name};
199	            return std::nullopt; // prt_art (degeneriert) + unbekannte
200	        };
201	        if (auto b = pick(lebewesen))
202	            return SotaModule{lebewesen + "+prt(St2)", sota_binary_id(reihe, std::string{b->name}),
203	                              std::string{b->type}, "compositions/prt_art_merge_reference.hpp",
204	                              lebewesen}; // host_lebewesen == lebewesen: der per-Host-Replace hat DIESEN Host
205	        return std::nullopt;
206	    }
207	    if (merge == "Stufe3_FullJoin") {
208	        // AP-4/#238: per-Host-FullJoin (analog build_sota_series_a_modules) — je SOTA-Host eine distinkte
209	        // <Host>PrtStufe3FullJoinComposition. prt_art-als-Host ist degeneriert (prt_art ist in Reihe A/Stufe1
210	        // bereits isoliert) → nullopt (ehrlich, keine Reihe-A-Duplikation unter B-Label).
211	        struct B {
212	            std::string_view type;
213	            std::string_view name;
214	        };
215	        auto pick = [&](std::string const& l) -> std::optional<B> {
216	            if (l == "art")
217	                return B{"::comdare::cache_engine::compositions::ArtPrtStufe3FullJoinComposition",
218	                         cmp::ArtPrtStufe3FullJoinComposition::name};
219	            if (l == "hot")
220	                return B{"::comdare::cache_engine::compositions::HotPrtStufe3FullJoinComposition",
221	                         cmp::HotPrtStufe3FullJoinComposition::name};
222	            if (l == "masstree")
223	                return B{"::comdare::cache_engine::compositions::MasstreePrtStufe3FullJoinComposition",
224	                         cmp::MasstreePrtStufe3FullJoinComposition::name};
225	            if (l == "surf")
226	                return B{"::comdare::cache_engine::compositions::SurfPrtStufe3FullJoinComposition",
227	                         cmp::SurfPrtStufe3FullJoinComposition::name};
228	            if (l == "start")
229	                return B{"::comdare::cache_engine::compositions::StartPrtStufe3FullJoinComposition",
230	                         cmp::StartPrtStufe3FullJoinComposition::name};
231	            if (l == "wormhole")
232	                return B{"::comdare::cache_engine::compositions::WormholePrtStufe3FullJoinComposition",
233	                         cmp::WormholePrtStufe3FullJoinComposition::name};
234	            return std::nullopt; // prt_art (degeneriert) + unbekannte
235	        };
236	        if (auto b = pick(lebewesen))
237	            return SotaModule{lebewesen + "+prt(St3)", sota_binary_id(reihe, std::string{b->name}),
238	                              std::string{b->type}, "compositions/prt_art_merge_reference.hpp",
239	                              lebewesen}; // host_lebewesen == lebewesen: der per-Host-FullJoin hat DIESEN Host
240	        return std::nullopt;
241	    }
242	    return std::nullopt;
243	}
