246	/// deklarierte <sota_series id lebewesen merge> ein Eintrag binary_id → reale Modul-Quelle. KEINE
247	/// Selektion (die Reihen/Lebewesen kommen aus dem Profil); je Eintrag genau EIN realer perm-DLL-Quelltext.
248	[[nodiscard]] inline std::map<std::string, std::string> build_sota_source_map(cx::ThesisProfile const& tp) {
249	    std::map<std::string, std::string> by_id;
