275	// #171 (Text-Agent AP-X2/TODO-2, 2026-06-20) — die Pruefling-Auspraegung "full" vs "abstract" als 1:1-Sicht auf
276	//   die BESTEHENDE MergeStrategy/sota_series-Mechanik (KEINE neue Achse, KEINE neue Selektion):
277	//     • full     == "Originalkonfiguration"/self-contained == Reihe A == merge=Stufe1_CeOnly: das Lebewesen
278	//                   fuellt ALLE 19 Achsen mit EIGENEN Organen (PrtArtComposition / die 6 SOTA isoliert).
279	//                   Beleg: pruefling_merge.hpp:93-95 StufeOneAxis=DefaultList; prt_art_reference.hpp:61-80.
280	//     • abstract == Teilmenge + Host-Fallback == Stufe2/Reihe A oder Stufe3/Reihe B:
281	//                   der Pruefling fuellt NUR einen Slot (path_compression), 18 Achsen via Host-Fallback.
282	//                   Beleg: pruefling_merge.hpp:113-118 conditional_t Ersetzt-mit-Fallback; prt_art_merge_reference.hpp.
283	//   Quelle der cacheline-doc §0 Z.11 / §1.2 Z.19 ("Paper-Algorithmen als Basis-Lebewesen in Originalkonfiguration").
284	//   Die Ableitung ist DETERMINISTISCH aus merge (bzw. series-id als Fallback); ein explizites
285	//   <sota_series pruefling_type=".."/> uebersteuert sie. Single-Source hier → kein verstreuter String-Vergleich.
286	[[nodiscard]] inline std::string derive_pruefling_type(std::string const& series_id, std::string const& merge,
287	                                                       std::string const& explicit_override) {
288	    if (!explicit_override.empty()) return explicit_override; // Forscher-Override gewinnt
289	    // Primaer aus merge (die mechanische Wahrheit): Stufe1 = self-contained = full; Stufe2/3 = Teilmenge = abstract.
290	    if (merge == "Stufe1_CeOnly") return "full";
291	    if (merge == "Stufe2_PrueflingReplace") return "abstract";
292	    if (merge == "Stufe3_FullJoin") return "abstract";
293	    // Fallback wenn merge leer/unbekannt: aus der Reihen-id (A=full, B/C=abstract) — kongruent zur merge-Map.
294	    if (series_id == "A") return "full";
295	    if (series_id == "B" || series_id == "C") return "abstract";
296	    return "-"; // weder ableitbar noch gesetzt (kein Phantom-Typ)
297	}
