299	// Ein profil-deklariertes SOTA-Reihen-Lebewesen, aufbereitet als EIN Treiber-Pass (Reihe-Tag + view-binary_id).
300	struct SotaPass {
301	    std::string
302	        series; // #178: Reihe aus Stufe abgeleitet (stufe_to_reihe): "A" (St1∪St2) / "B" (St3); C=build-übergr. (CSV-Tag row_series)
303	    std::string lebewesen;      // Profil-Lebewesen-Name (Doku/Log)
304	    std::string sota_bid;       // der rohe sota::S::name (AxisLevel-Wert der einwertigen "sota_tier"-Ebene)
305	    std::string view_binary_id; // == "sota_tier=<sota::S::name>" (== StaticBinaryView-binary_id dieses Passes)
306	    std::string pruefling_type; // #171: "full" (Reihe A self-contained) / "abstract" (Stufe2/3 Teilmenge+Fallback)
307	    // GO-5 Fork 6 (2026-07-12, Thesis §sec:fairness): der deklarierte Fairness-Modus der Reihe —
308	    // "common_denominator" / "native" / "-" (ungesetzt = heutiges Verhalten). REINE Reihen-Metadaten
309	    // (CSV-Tag fairness_mode + Resume-Stamp), NICHT Teil der binary_id (Tags verschmutzen die
310	    // Round-Trip-Identitaet nie, LazyRunConfig-Doktrin). Die Kompositions-Pinnung des
311	    // common_denominator-Falls (value_handle_external + PRT-Spezialpfade aus) ist DATEN-gated
312	    // (#156/#162-Fenster) und aendert DANN die Komposition selbst (⇒ natuerlicherweise eigene binary_id).
313	    std::string fairness_mode = "-";
314	    // M-CE-10 (Voll-Review 2026-07-13; per-Host-Auffächerung 2026-07-14): das Lebewesen, dessen H2-Code-Qualitäts-
315	    // Score dieser Pass trägt — host-dominant (== SotaModule::host_lebewesen). Für St1/St2/St3 identisch zu
316	    // `lebewesen` (nach der per-Host-Auffächerung ist auch die St2-Komposition per-Host, host_lebewesen == lebewesen).
317	    // Der Treiber löst den CSV-Score über DIESES Feld auf (h2_score_for) — prt_art/fehlende Akte ⇒ honest "n/a".
318	    std::string h2_lebewesen = "-";
319	};
