360	/// build_sota_view_source_map(profile) — wie build_sota_source_map, ABER der Schlüssel ist der VIEW-binary_id
361	/// ("sota_tier=<sota::S::name>") statt des rohen sota::S::name. Das ist GENAU die Form, die der Treiber-View
362	/// (einwertige AxisLevel "sota_tier") je SOTA-Pass erzeugt → die SourceGenFn-Vereinigung (S7a) findet die Quelle
363	/// direkt über den View-binary_id (kein Re-Mapping im Treiber). Disjunkt zum Basis-320-Schlüsselraum.
364	[[nodiscard]] inline std::map<std::string, std::string> build_sota_view_source_map(cx::ThesisProfile const& tp) {
365	    std::map<std::string, std::string> by_id;
366	    for (auto const& s : tp.sota_series) {
367	        if (auto m = sota_module_for(s.merge, s.lebewesen)) // #178: dispatch auf die Stufe (merge), nicht den id
368	            by_id.emplace(sota_view_binary_id(m->binary_id), render_sota_module_source(m->composition_type, m->header));
369	    }

360	
361	    std::vector<std::string> const selection_passes = profile_sweep_passes(tp, a.sweep_axis);
362	    if (selection_passes.size() > 1)
363	        std::cout << "  [MULTI-SWEEP] Basis-Pass + " << (selection_passes.size() - 1)
364	                  << " deklarierte <axis_sweep>-Paesse (Dokument-Reihenfolge, #26/GO-5)\n";
365	    for (auto const& pass_axis : selection_passes) run_selection_pass(pass_axis);
366	    // Distinkte Basis-/Sweep-binary_ids DIESES Laufs (Baseline zaehlt ueber alle Paesse genau 1x). Im
367	    // Einzel-Pass-Fall identisch zur frueheren sel.indices.size()-Zaehlung (Selektionen sind duplikatfrei).
368	    res.basis_binary_ids = pass_seen_ids.size();
369	
370	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
371	    // S7b — PASS 2..k: je <sota_series> EIN SOTA-Reihen-Lebewesen (einwertiger "sota_tier"-Baum, Tag A/B/C).
372	    //   Disjunkter binary_id-Namensraum ("sota_tier=sota::S::name") → die union_gen liefert die SOTA-Quelle.
373	    // ════════════════════════════════════════════════════════════════════════════════════════════════════
374	    if (a.run_sota_series) {
375	        std::vector<SotaPass> const passes = build_sota_passes(tp);
376	        std::cout << "  [SOTA] real baubare <sota_series>-Paesse = " << passes.size() << " (von "
377	                  << tp.sota_series.size() << " deklariert)\n";
378	        // M-CE-10 (Voll-Review 2026-07-13, Fix (b)): res.sota_binary_ids ist per Doku "distinkte SOTA-Reihen-
379	        // binary_ids, die gebaut/gemessen wurden" — NICHT die Pass-Zahl. build_sota_passes dedupliziert bereits
380	        // identische Messungen (St2 = 1 HOT-Pilot); dieser Set-Guard fängt zusätzlich die legitimen fairness-
381	        // Varianten ab (gleiche binary_id, verschiedener fairness_mode ⇒ EINE reale DLL). So bleibt der Zähler
382	        // exakt == Zahl der real gebauten/gemessenen distinkten DLLs (kein Über-Zählen wie vor dem Fix).
383	        std::set<std::string> sota_seen_bids;
384	        for (auto const& p : passes) {
385	            // Einwertiger Static-Baum: AxisLevel "sota_tier"=<sota_bid> + dieselben DynamicDims wie der Basis-Baum
386	            // (damit die SOTA-Zeilen die gleiche thread_count×prefetch×repetition-Variation tragen).
387	            std::vector<ex::AxisLevel> sota_levels;
388	            sota_levels.push_back(ex::AxisLevel{std::string{kSotaTierAxis}, {p.sota_bid}, /*is_static=*/true, "", ""});
389	            for (auto const& dd : basis_tree.dynamic_filter())
390	                sota_levels.push_back(ex::AxisLevel{dd.axis, dd.values, /*is_static=*/false, dd.variable, dd.block_id});
391	
392	            auto               sota_factory = std::make_shared<ex::ExperimentNodeFactory>();
393	            ex::ExperimentTree sota_tree{sota_factory};
394	            sota_tree.build(sota_levels);

